package com.shoron.mono.wallpaper

import androidx.annotation.DrawableRes
import androidx.annotation.StringRes
import com.shoron.mono.R

/** An original MONO wallpaper bundled with the app (generated by tools/wallpapers/generate.py). */
data class BuiltInWallpaper(
    val id: String,
    @StringRes val nameRes: Int,
    @DrawableRes val resId: Int,
)

object WallpaperCatalog {

    const val DEFAULT_ID = "builtin:shoreline"

    val builtIns: List<BuiltInWallpaper> = listOf(
        BuiltInWallpaper(DEFAULT_ID, R.string.wallpaper_shoreline, R.drawable.wallpaper_shoreline),
        BuiltInWallpaper("builtin:undertow", R.string.wallpaper_undertow, R.drawable.wallpaper_undertow),
        BuiltInWallpaper("builtin:swell", R.string.wallpaper_swell, R.drawable.wallpaper_swell),
    )

    fun find(id: String): BuiltInWallpaper? = builtIns.firstOrNull { it.id == id }

    fun default(): BuiltInWallpaper = builtIns.first()
}
